export function FolderIngestPanel() {
  const [folder, setFolder] = useState('data/paper_cache');
  const [apply, setApply] = useState(false);
  const [limit, setLimit] = useState(0);
  const [force, setForce] = useState(false);
  const [concurrency, setConcurrency] = useState(16);
  const [thinkingBudget, setThinkingBudget] = useState(256);
  const [output, setOutput] = useState<'json' | 'tiled'>('json');
  const [corpusManifest, setCorpusManifest] = useState(false);
  const [priority, setPriority] = useState<'source' | 'scattering'>('scattering');
  const [status, setStatus] = useState<FolderIngestStatus | null>(null);
  const [error, setError] = useState('');
  const [stopping, setStopping] = useState(false);
  const [browsing, setBrowsing] = useState(false);
  const selectedModel = useResolvedModel('kg');

  const isRunning = status?.running === true;

  const refresh = useCallback(async () => {
    try {
      setStatus(await getFolderIngestStatus());
    } catch {
      // A poll failure is not worth a banner: the next tick usually succeeds,
      // and the start button surfaces anything that actually blocks a run.
    }
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  useEffect(() => {
    const id = setInterval(() => void refresh(), isRunning ? POLL_MS : IDLE_POLL_MS);
    return () => clearInterval(id);
  }, [isRunning, refresh]);

  const handleStart = async () => {
    setError('');
    try {
      await startFolderIngest({
        folder: folder.trim(),
        apply,
        limit: limit || undefined,
        force,
        extract_entities: true,
        model: selectedModel || undefined,
        concurrency,
        thinking_budget: thinkingBudget,
        output,
        corpus_manifest: corpusManifest,
        priority,
      });
      await refresh();

export async function startFolderIngest(
  params: FolderIngestParams,
): Promise<Record<string, unknown>> {
  const url = new URL(`${AGENT_URL}/api/graph/ingest_folder`);
  url.searchParams.set('folder', params.folder);
  if (params.apply != null) url.searchParams.set('apply', String(params.apply));
  if (params.limit) url.searchParams.set('limit', String(params.limit));
  if (params.force != null) url.searchParams.set('force', String(params.force));
  if (params.extract_entities != null) {
    url.searchParams.set('extract_entities', String(params.extract_entities));
  }
  if (params.model) url.searchParams.set('model', params.model);
  if (params.concurrency != null) url.searchParams.set('concurrency', String(params.concurrency));
  if (params.thinking_budget != null) url.searchParams.set('thinking_budget', String(params.thinking_budget));
  if (params.output) url.searchParams.set('output', params.output);
  if (params.corpus_manifest != null) url.searchParams.set('corpus_manifest', String(params.corpus_manifest));
  if (params.priority) url.searchParams.set('priority', params.priority);
  if (params.selection) url.searchParams.set('selection', params.selection);
  const res = await fetch(url.toString(), { method: 'POST', headers: adminHeaders() });
  if (!res.ok) {
    // THE BODY CARRIES THE REASON, and it is the useful half. A containment
    // refusal answers 400 with the allowed directories listed; showing only
    // "HTTP 400" would leave someone guessing at a path the server could have
    // told them.
    let detail = '';
    try {
      detail = ((await res.json()) as { detail?: string }).detail ?? '';
    } catch {
      // non-JSON body; the status alone will have to do
    }
    throw new Error(detail || `HTTP ${res.status}`);
  }
  return res.json() as Promise<Record<string, unknown>>;
}

