@app.on_event("startup")
async def _resume_interrupted_folder_ingest():
    """Recover after a lease expires; multiple API workers arbitrate in SQLite.

    The journal reads run in a worker thread: a SQLite call made on the event
    loop froze the whole service (every route, /health included) whenever the
    open queued behind other threads' SQLite work.
    """
    async def recover():
        while True:
            previous = None
            try:
                previous = await asyncio.to_thread(lambda: _ingest_journal().recoverable())
                if previous and previous["state"] == "running" and previous["lease_until"] < time.time():
                    if not previous["stop_requested"]:
                        config = dict(previous["config"])
                        config.pop("_pipeline", None)
                        if config.pop("kind", "folder") == "pdf_parse":
                            restarted = await start_pdf_parse(**config)
                        else:
                            restarted = await start_folder_ingest(**config)
                        current = await asyncio.to_thread(lambda: _ingest_journal().latest())
                        if restarted.get("started") and current and current["id"] != previous["id"]:
                            await asyncio.to_thread(
                                lambda: _ingest_journal().finish(previous["id"], previous["owner"], "superseded")
                            )
            except HTTPException:
                # A removed or no-longer-allowed folder cannot resume. Do not
                # let it terminate recovery for other interrupted jobs.
                if previous:
                    await asyncio.to_thread(
                        lambda: _ingest_journal().finish(previous["id"], previous["owner"], "failed")
                    )
                logger.warning("Interrupted ingest request is no longer valid", exc_info=True)
            except Exception:
                logger.warning("Ingest recovery failed; retrying in 30 seconds", exc_info=True)
            await asyncio.sleep(30)

