class CBorgControlRequest(BaseModel):
    """Paid resolver switch and cumulative spending ceiling."""

    enabled: bool
    budget_cap_usd: float = Field(ge=1, le=10_000, allow_inf_nan=False)


@app.post("/api/graph/uncertainty/cborg/control", dependencies=[Depends(require_admin_key)])
async def set_cborg_control(body: CBorgControlRequest) -> dict[str, Any]:
    """Pause or start paid resolution without disturbing local review."""
    from als_knowledge_agent.graph.cborg_control import (
        apply_control_environment,
        read_control,
        write_control,
    )
    from als_knowledge_agent.graph.cborg_resolution import resolution_worker

    current = read_control()
    task = getattr(app.state, "scientific_resolution_task", None)
    active = task is not None and not task.done()
    if current["enabled"] and body.budget_cap_usd != current["budget_cap_usd"]:
        raise HTTPException(409, detail="Pause CBorg before changing the budget")
    if body.enabled and not current["enabled"]:
        if active:
            raise HTTPException(409, detail="Previous CBorg requests are still draining")
        if os.getenv("ALS_SECOND_PASS_PROVIDER", "cborg").strip().lower() != "cborg":
            raise HTTPException(409, detail="CBorg is not the configured second-pass provider")
        if not os.getenv("CBORG_API_KEY"):
            raise HTTPException(409, detail="CBorg API key is not configured")
    write_control(body.enabled, body.budget_cap_usd)
    apply_control_environment(body.model_dump())
    if body.enabled and not active:
        app.state.cborg_resolution_stop = asyncio.Event()
        app.state.scientific_resolution_task = asyncio.create_task(
            resolution_worker(app.state.cborg_resolution_stop)
        )
    elif not body.enabled and active:
        app.state.cborg_resolution_stop.set()
    return await scientific_uncertainty_summary()
